# -*- coding: utf-8 -*-
"""v3.4 装配五查（D39）。用法：python3 work/五查.py <冻结原件> <v3.4 文件> <补丁单.md> <冲突选择.json>
1 原文每行仍在且顺序不变（只允许登记的退役后缀）
2 只增不减：新字数 = 原字数 + 插入字数 + 退役后缀字数（逐章同时比）
3 补丁单第九节列出的每条 07 规则，在 v3.4 里能找到（新增句的依据里，或去向写了"冻结原文"）
4 冲突：已登记退役的原句必须带退役标记；新增句里不得出现与之相反的旧说法
5 新增内容无禁用词（禁用词表本身所在的句子除外）"""
import re, sys, json
src_p, new_p, plan_p, conf_p = sys.argv[1:5]
src = open(src_p, encoding='utf8').read().split('\n')
new = open(new_p, encoding='utf8').read().split('\n')
plan = open(plan_p, encoding='utf8').read()
conf = json.load(open(conf_p, encoding='utf8'))
ret = {int(k): v for k, v in conf['retire'].items()}
fail = []
# 1
j = 0; added = []
for i, line in enumerate(src, 1):
    want = line + ret.get(i, '')
    while j < len(new) and new[j] != want:
        added.append(new[j]); j += 1
    if j == len(new): fail.append(f'1 原文第 {i} 行找不到：{line[:40]}'); break
    j += 1
added += new[j:]
print('查1 原文行', len(src), '全部按序找到' if not any(f.startswith('1') for f in fail) else '有缺')
# 2
ins_txt = '\n'.join(added)
exp = len('\n'.join(src)) + sum(len(v) for v in ret.values()) + len(''.join(added)) + len(added)
got = len('\n'.join(new))
print('查2 原字数', len('\n'.join(src)), '新字数', got, '预期', exp)
if got != exp: fail.append('2 字数对不上')
def sec(lines):
    d = {}; k = '开头'
    for l in lines:
        if l.startswith('【'): k = l.split('】')[0] + '】'
        d[k] = d.get(k, 0) + len(l)
    return d
a, b = sec(src), sec(new)
for k in a:
    if b.get(k, 0) < a[k]: fail.append(f'2 章节变短：{k}')
print('查2 逐章', '无一章变短' if not any('变短' in f for f in fail) else '有章变短')
# 3  每行去向：写了补丁号的，该补丁的插入内容必须原样在新文件里；写"冻结原文第 N 行"的，该行必须仍在；写"C4"这类未采用冲突的，冲突选择里不得有它
tab = plan.split('## 九、')[1]
bodies = dict((pid, b.rstrip('\n')) for pid, b in re.findall(r'### (P\d+)｜新增｜.*?插入：\n```\n(.*?)```', plan, re.S))
newtxt = '\n'.join(new)
miss = []
for left, right in re.findall(r'^\| (.+?) \| (.+?) \|$', tab, re.M):
    if left.startswith('07 规则') or set(left) <= set('-'): continue
    pids = re.findall(r'P\d+', right)
    for pid in pids:
        if bodies[pid] not in newtxt: miss.append(f'{left}→{pid} 未装')
    for n in re.findall(r'第 ([\d、～]+) 行', right):
        for x in re.findall(r'\d+', n):
            if int(x) > len(src): miss.append(f'{left}→原文第{x}行不存在')
    if not pids and '冻结原文' not in right and not re.search(r'C\d', right): miss.append(f'{left} 无去向')
print('查3 07 规则落地', '全部找到' if not miss else f'缺 {miss}')
if miss: fail.append(f'3 缺 {miss}')
# 4
for i in ret:
    if not new[[n for n, l in enumerate(new) if l.startswith(src[i-1])][0]].endswith(ret[i]): fail.append(f'4 第 {i} 行没带退役标记')
for bad in ['最多装配 2 个', '顿半拍后', '慢悠悠地']:
    for l in added:
        if bad in l and '禁用' not in l and '不写' not in l and '退役' not in l: fail.append(f'4 新增句出现旧说法：{bad}')
print('查4 冲突', '通过' if not any(f.startswith('4') for f in fail) else '有冲突')
# 5
BAN = ['慢悠悠', '拖长', '拖腔', '拉长', '一字一顿', '逐字', '字字咬', '慢条斯理', '缓缓', '放慢', '顿半拍', '停一拍',
       '面如死灰', '石化', '脸色发白', '铁青', '满脸通红', '像疯子']
hit = []
for l in added:
    if any(w in l for w in BAN) and not re.search(r'禁用|不写|不许|不要|改成|换成|写了模型|成片证据', l):
        hit.append(l[:50])
print('查5 禁用词', '无' if not hit else hit)
if hit: fail.append('5 禁用词')
print('五查', '通过' if not fail else '失败：' + '；'.join(fail))
sys.exit(1 if fail else 0)

